const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(path,data){const r=await fetch('/api/admin/'+path,{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined});const v=await r.json();if(!r.ok)throw Error(v.error);return v;}
async function upload(file){const fd=new FormData();fd.set('file',file);const r=await fetch('/api/admin/service-upload',{method:'POST',body:fd}),v=await r.json();if(!r.ok)throw Error(v.error);return v.url;}
export async function mountSettings(root,message){const s=await api('service-settings');root.innerHTML=`<form class="panel" data-settings><h2>Service content & terms</h2><p>Changes publish immediately. Edit product prices in Catalog → Options & Pricing.</p>${[['designEmail','Design contact email'],['designTerms','Design agreement'],['installationTerms','Installation terms'],['bookingNote','Booking confirmation note'],['filePrep','Default print file preparation'],['fileGuide','Print guide link'],['wallGuide','Wallpaper materials & installation'],['detailingIntro','Detailing introduction'],['detailingAftercare','Detailing aftercare']].map(([k,l])=>`<label style="display:block;margin:20px 0">${l}${k==='designEmail'||k==='fileGuide'?`<input name="${k}" value="${esc(s[k])}">`:`<textarea name="${k}" rows="${k.endsWith('Terms')?12:4}">${esc(s[k])}</textarea>`}</label>`).join('')}<h2>Home promotion slider</h2><p>Edit title, text, button, link and image for every slide. Each line below is one slide; drag the slide rows to reorder them.</p><fieldset><legend>Slider display</legend><label>Seconds per slide<input name="promo.intervalSeconds" type="number" min="3" max="60" value="${s.promotionDisplay.intervalSeconds}"></label><label><input name="promo.autoplay" type="checkbox" ${s.promotionDisplay.autoplay?'checked':''}>Automatically rotate slides</label><label>Background<input name="promo.background" type="color" value="${esc(s.promotionDisplay.background)}"></label><label>Text colour<input name="promo.textColor" type="color" value="${esc(s.promotionDisplay.textColor)}"></label></fieldset><div data-promotions></div><button type="button" data-promo-add>Add promotion</button><h2>Videography partner and plans</h2><label>Heading<input name="video.title" value="${esc(s.videoPartner.title)}"></label><label>Introduction<textarea name="video.text">${esc(s.videoPartner.text)}</textarea></label>${s.videoPartner.plans.map((p,i)=>`<fieldset><legend>Video plan ${i+1}</legend>${['name','price','detail'].map(k=>`<label>${k}<input name="video.${i}.${k}" value="${esc(p[k])}"></label>`).join('')}</fieldset>`).join('')}<p>Enter confirmed prices here. Unconfirmed partner pricing stays on request.</p><h2>Appointment times · Toronto</h2><p>These are times customers can request. Confirmed appointments are removed from the list. Staff must confirm each request.</p><div class="form-grid">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map((d,i)=>`<label><input type="checkbox" name="day" value="${i}" ${s.bookingDays.includes(i)?'checked':''}>${d}</label>`).join('')}</div><label>Times · one per line, 24-hour format<textarea name="bookingTimes" rows="5">${esc(s.bookingTimes.join('\n'))}</textarea></label><label>Closed dates · YYYY-MM-DD, one per line<textarea name="closedDates" rows="3">${esc(s.closedDates.join('\n'))}</textarea></label>${['printBanner','wallBanner'].map(k=>`<h2>${k==='printBanner'?'Print Shop':'Wallpaper'} banner</h2><div class="form-grid">${['title','text','image',...(k==='printBanner'?['link']:[])].map(f=>`<label>${f}<input name="${k}.${f}" value="${esc(s[k][f])}"></label>`).join('')}<label>Upload banner photo<input type="file" data-banner="${k}" accept="image/png,image/jpeg,image/webp"></label></div>`).join('')}<h2>Detailing plans</h2><div data-plans>${s.detailingPlans.map((p,i)=>`<fieldset style="margin:16px 0;padding:20px"><legend>Plan ${i+1}</legend>${['name','price','image'].map(k=>`<label>${k}<input name="plan.${i}.${k}" value="${esc(p[k])}"></label>`).join('')}<label>Features · one per line<textarea name="plan.${i}.features" rows="4">${esc(p.features.join('\n'))}</textarea></label><label>Upload photo<input type="file" data-plan-photo="${i}" accept="image/*"></label></fieldset>`).join('')}</div><h2>PPF plan descriptions</h2>${s.ppfPlans.map((p,i)=>`<div class="form-grid"><label>Plan name<input name="ppf.${i}.name" value="${esc(p.name)}"></label><label>Coverage<textarea name="ppf.${i}.detail">${esc(p.detail)}</textarea></label></div>`).join('')}<p>PPF prices and choices: Catalog → Options & Pricing → Partial PPF packages / Full vehicle PPF.</p><button class="primary">Save & publish settings</button></form>`;
const promos=structuredClone(s.promotions||[]);const promoArea=root.querySelector('[data-promotions]');let dragged=-1;const paintPromos=()=>{promoArea.innerHTML=promos.map((p,i)=>`<fieldset draggable="true" data-promo="${i}"><legend>Slide ${i+1}</legend>${['title','text','button','link','image'].map(k=>`<label>${k}<input data-promo-key="${k}" value="${esc(p[k])}"></label>`).join('')}<label><input type="checkbox" data-promo-key="active" ${p.active!==false?'checked':''}>Active</label><label>Upload image<input type="file" data-promo-image accept="image/png,image/jpeg,image/webp"></label><button type="button" data-promo-remove>Remove slide</button></fieldset>`).join('');};paintPromos();promoArea.oninput=e=>{const row=e.target.closest('[data-promo]'),key=e.target.dataset.promoKey;if(row&&key)promos[+row.dataset.promo][key]=key==='active'?e.target.checked:e.target.value;};promoArea.onclick=e=>{const row=e.target.closest('[data-promo]');if(row&&e.target.hasAttribute('data-promo-remove')){promos.splice(+row.dataset.promo,1);paintPromos();}};promoArea.ondragstart=e=>{dragged=+e.target.closest('[data-promo]').dataset.promo;};promoArea.ondragover=e=>e.preventDefault();promoArea.ondrop=e=>{e.preventDefault();const row=e.target.closest('[data-promo]');if(row&&dragged>=0){const [p]=promos.splice(dragged,1);promos.splice(+row.dataset.promo,0,p);paintPromos();}};root.querySelector('[data-promo-add]').onclick=()=>{promos.push({title:'New promotion',text:'',button:'Learn more',link:'/satin/contact',image:'/satin/img/window-vinyl.png',active:true});paintPromos();};
root.onchange=async e=>{if(e.target.hasAttribute('data-promo-image')){try{const i=+e.target.closest('[data-promo]').dataset.promo;promos[i].image=await upload(e.target.files[0]);paintPromos();}catch(err){message(err.message,true);}return;}const k=e.target.dataset.banner,i=e.target.dataset.planPhoto;if(k===undefined&&i===undefined)return;try{message('Uploading…');const url=await upload(e.target.files[0]);root.querySelector(`[name="${k?k+'.image':'plan.'+i+'.image'}"]`).value=url;message('Uploaded. Save settings to publish.');}catch(err){message(err.message,true);}};
root.querySelector('form').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target),v={...s,promotions:promos};v.promotionDisplay={intervalSeconds:Number(fd.get("promo.intervalSeconds")),autoplay:fd.has("promo.autoplay"),background:fd.get("promo.background"),textColor:fd.get("promo.textColor")};v.videoPartner={title:fd.get("video.title"),text:fd.get("video.text"),plans:s.videoPartner.plans.map((p,i)=>Object.fromEntries(["name","price","detail"].map(k=>[k,fd.get("video."+i+"."+k)])))};for(const k of ['designEmail','designTerms','installationTerms','bookingNote','filePrep','fileGuide','wallGuide','detailingIntro','detailingAftercare'])v[k]=fd.get(k);v.bookingDays=fd.getAll('day').map(Number);for(const k of ['bookingTimes','closedDates'])v[k]=fd.get(k).split(/\n|,/).map(x=>x.trim()).filter(Boolean);for(const k of ['printBanner','wallBanner'])v[k]=Object.fromEntries(Object.keys(s[k]).map(f=>[f,fd.get(k+'.'+f)]));v.detailingPlans=s.detailingPlans.map((p,i)=>({...p,...Object.fromEntries(['name','price','image'].map(k=>[k,fd.get('plan.'+i+'.'+k)])),features:fd.get('plan.'+i+'.features').split('\n').filter(Boolean)}));v.ppfPlans=s.ppfPlans.map((p,i)=>({...p,name:fd.get('ppf.'+i+'.name'),detail:fd.get('ppf.'+i+'.detail')}));try{await api('service-settings',v);message('Settings published.');}catch(err){message(err.message,true);}};}
export async function mountProjects(root,message){let {projects}=await api('projects');const list=()=>{root.innerHTML=`<div class="panel"><div class="row"><h2>Our Work · ${projects.length} projects</h2><button data-new class="primary">Add project</button></div><label>Find a project<input data-search type="search" placeholder="Title or vehicle"></label><div data-project-list></div></div>`;const draw=q=>{root.querySelector('[data-project-list]').innerHTML=projects.filter(p=>(p.title+' '+p.vehicle).toLowerCase().includes(q)).map(p=>`<button data-edit="${esc(p.id)}" style="display:flex;align-items:center;gap:16px;width:100%;text-align:left;padding:12px;border-bottom:1px solid #ddd"><img src="${esc(p.cover?.src||p.images[0].src)}" width="90" height="60" style="object-fit:cover"><span><b>${esc(p.title)}</b><br>${esc(p.vehicle)} · ${p.images.length} photos ${p.active===false?'· Hidden':''}</span></button>`).join('');};draw('');root.querySelector('[data-search]').oninput=e=>draw(e.target.value.toLowerCase());root.onclick=e=>{if(e.target.closest('[data-new]'))edit({id:crypto.randomUUID(),slug:'',title:'',category:'commercial',vehicle:'Van',industry:'',coverage:'Full Wrap',description:'',active:true,images:[]});const b=e.target.closest('[data-edit]');if(b)edit(structuredClone(projects.find(p=>p.id===b.dataset.edit)));};};
const edit=p=>{root.onclick=null;root.innerHTML=`<form class="panel"><button type="button" data-back>← Projects</button><h2>${p.title?'Edit project':'New project'}</h2><div class="form-grid">${['title','slug','vehicle','industry','coverage'].map(k=>`<label>${k}<input name="${k}" value="${esc(p[k])}" ${['title','slug'].includes(k)?'required':''}></label>`).join('')}<label>Category<select name="category"><option value="commercial" ${p.category==='commercial'?'selected':''}>Commercial wrap</option><option value="colour" ${p.category==='colour'?'selected':''}>Colour change</option></select></label></div><label>Description<textarea name="description" rows="5">${esc(p.description)}</textarea></label><label><input type="checkbox" name="active" ${p.active!==false?'checked':''}>Published</label><h3>Photos · first image is the cover</h3><div data-photo-list></div><label>Add photos<input type="file" multiple accept="image/png,image/jpeg,image/webp" data-upload></label><button class="primary">Save project</button></form>`;const draw=()=>{root.querySelector('[data-photo-list]').innerHTML=p.images.map((im,i)=>`<div style="display:flex;align-items:center;gap:10px;margin:10px 0"><img src="${esc(im.src)}" width="110" height="75" style="object-fit:cover"><input data-alt="${i}" value="${esc(im.alt||p.title)}" aria-label="Photo description"><button type="button" data-up="${i}" ${i===0?'disabled':''}>↑</button><button type="button" data-remove="${i}">Remove</button></div>`).join('');};draw();root.onclick=e=>{if(e.target.closest('[data-back]'))list();const b=e.target.closest('[data-remove],[data-up]');if(!b)return;if(b.dataset.remove!==undefined)p.images.splice(+b.dataset.remove,1);else{const i=+b.dataset.up;[p.images[i-1],p.images[i]]=[p.images[i],p.images[i-1]];}draw();};root.onchange=async e=>{if(e.target.dataset.alt!==undefined)p.images[+e.target.dataset.alt].alt=e.target.value;if(e.target.matches('[data-upload]')){try{message('Uploading photos…');for(const file of e.target.files){p.images.push({src:await upload(file),alt:p.title});}draw();message('Photos uploaded. Save to publish.');}catch(err){message(err.message,true);}}};root.querySelector('[name=title]').oninput=e=>{if(!p.slug)root.querySelector('[name=slug]').value=e.target.value.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');};root.querySelector('form').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target);for(const k of ['title','slug','vehicle','industry','coverage','category','description'])p[k]=fd.get(k);p.active=fd.has('active');try{await api('projects',{project:p});projects=(await api('projects')).projects;list();message('Project published.');}catch(err){message(err.message,true);}};};list();}
